select st.id, sj.id, '11111111-1111-1111-1111-111111111111', src.kind, src.score, src.max_score
  from src
  join public.students st on st.college_id = '11111111-1111-1111-1111-111111111111' and st.reg_no = src.reg_no
  join public.subjects sj on sj.college_id = '11111111-1111-1111-1111-111111111111' and sj.code   = src.code
on conflict do nothing;